"""Every referenced id must exist in the approved scope or in a prior artifact."""

import re
from typing import Any

from pydantic import BaseModel

from app.ai.findings import Finding, FindingLevel

# Scope item prefixes plus the element prefixes generated by the artifacts.
ID_PATTERN = re.compile(
    r"^(?:BR|PER|FR|NFR|SYS|INT|DATA|SEC|TECH|CON|DEP|RISK|GAP|ASM|Q"
    r"|CAP|MOD|WS|DP|ENH|ARC|IA|AI|DOM)_\d+$"
)
# Ids that point at documents, not at scope items.
_SKIPPED_KEYS = {"document_id", "segment_id", "session_id"}


def _is_id(value: Any) -> bool:
    return isinstance(value, str) and bool(ID_PATTERN.match(value))


def _walk(node: Any, path: str, defined: set[str], refs: dict[str, list[str]]) -> None:
    if isinstance(node, BaseModel):
        _walk(node.model_dump(), path, defined, refs)
        return
    if isinstance(node, dict):
        for key, value in node.items():
            child = f"{path}.{key}" if path else str(key)
            if key == "id" and _is_id(value):
                defined.add(value)
                continue
            if key in _SKIPPED_KEYS:
                continue
            if key.endswith("_ids"):
                # Every entry of an id list is a reference, whatever its prefix: an invented
                # id such as REQ_01 must be caught, not ignored.
                for found in _strings(value):
                    if found.strip():
                        refs.setdefault(found, []).append(child)
                continue
            if key.endswith("_id"):
                # A single id field may hold a name by design (a flow endpoint such as
                # "Broker Portal" becomes an external node), so only id-shaped values count.
                if _is_id(value):
                    refs.setdefault(value, []).append(child)
                continue
            _walk(value, child, defined, refs)
        return
    if isinstance(node, list):
        for index, value in enumerate(node):
            _walk(value, f"{path}[{index}]", defined, refs)


def _strings(value: Any) -> list[str]:
    return [item for item in value if isinstance(item, str)] if isinstance(value, list) else []


def collect_references(content: Any) -> tuple[set[str], dict[str, list[str]]]:
    """Return (ids defined inside the content, referenced id -> field paths)."""
    defined: set[str] = set()
    refs: dict[str, list[str]] = {}
    _walk(content, "", defined, refs)
    return defined, refs


def check_id_references(
    content: Any, known_ids: set[str], level: FindingLevel = FindingLevel.ERROR
) -> list[Finding]:
    """Flag referenced ids that exist neither in the scope nor in the content itself."""
    defined, refs = collect_references(content)
    allowed = known_ids | defined
    findings: list[Finding] = []
    for ref in sorted(refs):
        if ref in allowed:
            continue
        where = ", ".join(sorted(set(refs[ref]))[:3])
        findings.append(
            Finding(
                level=level,
                message=f"unknown id {ref} referenced at {where}; use an id from the scope",
                ids=[ref],
            )
        )
    return findings
